export const ALL_PROBLEMS = [

  // ─── CALCULATION (47 problems) ────────────────────────────────

  // Gram ↔ mol
  {id:'p01', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'How many moles are in 45.0 g of water (H2O)?', answer:2.499, unit:'mol', tolerance:0.02, solution:'<p>Find the molar mass first: M(H2O) = 2(1.008) + 15.999 = 18.015 g/mol.</p><p>Now convert grams to moles with n = m ÷ M.</p><p>n = 45.0 ÷ 18.015 = <strong>2.499 mol</strong></p>'},
  {id:'p02', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'How many grams is 3.25 mol of NaCl?', answer:189.94, unit:'g', tolerance:0.5, solution:'<p>Use m = n × M.</p><p>M(NaCl) = 22.990+35.453 = 58.443 g/mol</p><p>m = 3.25 × 58.443 = <strong>189.9 g</strong></p>'},
  {id:'p03', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'How many moles are in 85.0 g of ammonia (NH3)?', answer:4.991, unit:'mol', tolerance:0.05, solution:'<p>Use n = m ÷ M.</p><p>M(NH3) = 14.007+3(1.008) = 17.031 g/mol</p><p>n = 85.0 ÷ 17.031 = <strong>4.991 mol</strong></p>'},
  {id:'p04', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'What is the mass of 0.750 mol of ethanol (C2H5OH)?', answer:34.55, unit:'g', tolerance:0.2, solution:'<p>Use m = n × M.</p><p>M(C2H5OH) = 2(12.011)+6(1.008)+15.999 = 46.069 g/mol</p><p>m = 0.750 × 46.069 = <strong>34.55 g</strong></p>'},
  {id:'p05', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'How many moles are in 72.0 g of sodium hydroxide (NaOH)?', answer:1.800, unit:'mol', tolerance:0.02, solution:'<p>Use n = m ÷ M.</p><p>M(NaOH) = 22.990+15.999+1.008 = 39.997 g/mol</p><p>n = 72.0 ÷ 39.997 = <strong>1.800 mol</strong></p>'},
  {id:'p06', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'What is the mass of 4.50 mol of potassium hydroxide (KOH)?', answer:252.47, unit:'g', tolerance:0.5, solution:'<p>Use m = n × M.</p><p>M(KOH) = 39.098+15.999+1.008 = 56.105 g/mol</p><p>m = 4.50 × 56.105 = <strong>252.5 g</strong></p>'},
  {id:'p07', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'What is the mass of 0.500 mol of glucose (C6H12O6)?', answer:90.08, unit:'g', tolerance:0.2, solution:'<p>Use m = n × M.</p><p>M(C6H12O6) = 6(12.011)+12(1.008)+6(15.999) = 180.156 g/mol</p><p>m = 0.500 × 180.156 = <strong>90.08 g</strong></p>'},

  // Mol ↔ particles
  {id:'p08', difficulty:'easy', type:'calc', tag:'Mol–Particles', q:'How many molecules are in 2.00 mol of CO2?', answer:1.2044e24, unit:'molecules', tolerance:2e22, solution:'<p>N = n × Nₐ = 2.00 × 6.022×10^23 = <strong>1.204 × 10^24 molecules</strong></p>'},
  {id:'p09', difficulty:'easy', type:'calc', tag:'Mol–Particles', q:'How many moles are in 3.61 × 10^24 atoms of iron (Fe)?', answer:5.995, unit:'mol', tolerance:0.05, solution:'<p>n = 3.61×10^24 ÷ 6.022×10^23 = <strong>5.995 mol</strong></p>'},
  {id:'p10', difficulty:'medium', type:'calc', tag:'Mol–Particles', q:'How many molecules are in 11.5 g of water (H2O)?', answer:3.844e23, unit:'molecules', tolerance:5e21, solution:'<p>This is a two-step conversion: grams → moles → molecules.</p><p>mol H2O = 11.5 ÷ 18.015 = 0.6384 mol</p><p>N = 0.6384 × 6.022×10^23 = <strong>3.84 × 10^23 molecules</strong></p>'},
  {id:'p11', difficulty:'medium', type:'calc', tag:'Mol–Particles', q:'What is the mass of 6.022 × 10^22 molecules of glucose (C6H12O6)?', answer:18.016, unit:'g', tolerance:0.1, solution:'<p>mol = 6.022×10^22 ÷ 6.022×10^23 = 0.1000 mol<br>m = 0.1000 × 180.156 = <strong>18.02 g</strong></p>'},
  {id:'p12', difficulty:'easy', type:'calc', tag:'Mol–Particles', q:'How many moles of atoms are in 1.00 mol of H2SO4?', answer:7.00, unit:'mol atoms', tolerance:0.01, solution:'<p>H2SO4 has 2+1+1+4 = 7 atoms per formula unit<br>1.00 mol × 7 = <strong>7.00 mol atoms</strong></p>'},
  {id:'p13', difficulty:'medium', type:'calc', tag:'Mol–Particles', q:'How many atoms of hydrogen are in 9.03 g of H2O?', answer:6.037e23, unit:'H atoms', tolerance:5e21, solution:'<p>Convert the mass of water to moles first.</p><p>mol H2O = 9.03 ÷ 18.015 = 0.5013 mol</p><p>Each H2O has 2 hydrogen atoms, so mol H = 0.5013 × 2 = 1.0026 mol H atoms.</p><p>atoms H = 1.0026 × 6.022×10^23 = <strong>6.04 × 10^23</strong></p>'},
  {id:'p14', difficulty:'medium', type:'calc', tag:'Mol–Particles', q:'How many molecules are in 5.00 g of hydrogen chloride (HCl)?', answer:8.258e22, unit:'molecules', tolerance:5e20, solution:'<p>Use N = n × Nₐ (convert grams → moles → molecules).</p><p>M(HCl) = 1.008+35.453 = 36.461 g/mol</p><p>mol = 5.00 ÷ 36.461 = 0.1372 mol</p><p>N = 0.1372 × 6.022×10^23 = <strong>8.26 × 10^22 molecules</strong></p>'},
  {id:'p15', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'A gas sample has 8.00 × 10^23 molecules. What volume does it occupy at STP?', answer:29.77, unit:'L', tolerance:0.2, solution:'<p>mol = 8.00×10^23 ÷ 6.022×10^23 = 1.329 mol<br>V = 1.329 × 22.414 = <strong>29.77 L</strong></p>'},
  {id:'p16', difficulty:'easy', type:'calc', tag:'Mol–Particles', q:'How many moles are represented by 9.03 × 10^23 molecules of N2?', answer:1.500, unit:'mol', tolerance:0.015, solution:'<p>n = 9.03×10^23 ÷ 6.022×10^23 = <strong>1.500 mol</strong></p>'},
  {id:'p17', difficulty:'easy', type:'calc', tag:'Mol–Particles', q:'How many moles are in 4.215 × 10^24 molecules of any substance?', answer:6.999, unit:'mol', tolerance:0.05, solution:'<p>n = 4.215×10^24 ÷ 6.022×10^23 = <strong>6.999 mol ≈ 7.00 mol</strong></p>'},
  {id:'p18', difficulty:'medium', type:'calc', tag:'Mol–Particles', q:'What is the mass of 3.011 × 10^23 molecules of NH3?', answer:8.516, unit:'g', tolerance:0.1, solution:'<p>mol = 3.011×10^23 ÷ 6.022×10^23 = 0.5000 mol<br>m = 0.5000 × 17.031 = <strong>8.516 g</strong></p>'},

  // Molar mass
  {id:'p19', difficulty:'medium', type:'calc', tag:'Molar Mass', q:'What is the molar mass of Ca3(PO4)2?', answer:310.18, unit:'g/mol', tolerance:0.3, solution:'<p>Count each atom in Ca3(PO4)2: 3 Ca, 2 P, and 8 O.</p><p>Now add each contribution.</p><p>3(40.078) + 2(30.974) + 8(15.999)</p><p>= 120.234 + 61.948 + 127.992 = <strong>310.174 g/mol</strong></p>'},
  {id:'p20', difficulty:'medium', type:'calc', tag:'Molar Mass', q:'What is the molar mass of C12H22O11 (sucrose)?', answer:342.297, unit:'g/mol', tolerance:0.3, solution:'<p>Use M = Σ(count × atomic mass) for each element.</p><p>12(12.011)+22(1.008)+11(15.999)</p><p>= 144.132+22.176+175.989 = <strong>342.297 g/mol</strong></p>'},
  {id:'p21', difficulty:'medium', type:'calc', tag:'Molar Mass', q:'What is the molar mass of magnesium nitrate, Mg(NO3)2?', answer:148.313, unit:'g/mol', tolerance:0.2, solution:'<p>24.305 + 2(14.007) + 6(15.999)<br>= 24.305+28.014+95.994 = <strong>148.313 g/mol</strong></p>'},
  {id:'p22', difficulty:'medium', type:'calc', tag:'Molar Mass', q:'What is the molar mass of Al2(SO4)3?', answer:342.147, unit:'g/mol', tolerance:0.3, solution:'<p>2(26.982) + 3(32.065) + 12(15.999)<br>= 53.964+96.195+191.988 = <strong>342.147 g/mol</strong></p>'},
  {id:'p23', difficulty:'medium', type:'calc', tag:'Molar Mass', q:'What is the molar mass of (NH4)2SO4 (ammonium sulfate)?', answer:132.139, unit:'g/mol', tolerance:0.2, solution:'<p>2(14.007)+8(1.008)+32.065+4(15.999)<br>= 28.014+8.064+32.065+63.996 = <strong>132.139 g/mol</strong></p>'},
  {id:'p24', difficulty:'easy', type:'calc', tag:'Molar Mass', q:'What is the molar mass of silver nitrate (AgNO3)?', answer:169.872, unit:'g/mol', tolerance:0.2, solution:'<p>107.868+14.007+3(15.999)<br>= 107.868+14.007+47.997 = <strong>169.872 g/mol</strong></p>'},
  {id:'p25', difficulty:'easy', type:'calc', tag:'Molar Mass', q:'What is the molar mass of iron(II,III) oxide, Fe3O4 (magnetite)?', answer:231.531, unit:'g/mol', tolerance:0.3, solution:'<p>3(55.845)+4(15.999)<br>= 167.535+63.996 = <strong>231.531 g/mol</strong></p>'},

  // Percent composition
  {id:'p26', difficulty:'medium', type:'calc', tag:'Percent Composition', q:'How many grams of O are in 25.0 g of H2SO4?', answer:16.31, unit:'g', tolerance:0.1, solution:'<p>Use % by mass = (mass of element ÷ molar mass) × 100.</p><p>M(H2SO4) = 98.077 g/mol; 4 O atoms: 4×15.999 = 63.996 g/mol</p><p>%O = 63.996÷98.077×100 = 65.25%</p><p>mass O = 0.6525 × 25.0 = <strong>16.31 g</strong></p>'},
  {id:'p27', difficulty:'easy', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of nitrogen in NH4NO3?', answer:35.00, unit:'%', tolerance:0.3, solution:'<p>Use % by mass = (mass of element ÷ molar mass) × 100.</p><p>M(NH4NO3) = 80.043 g/mol; 2 N: 2×14.007 = 28.014 g/mol</p><p>%N = 28.014÷80.043×100 = <strong>35.00%</strong></p>'},
  {id:'p28', difficulty:'easy', type:'calc', tag:'Percent Composition', q:'Find the percent by mass of sulfur in SO3.', answer:40.05, unit:'%', tolerance:0.2, solution:'<p>Use % by mass = (mass of element ÷ molar mass) × 100.</p><p>M(SO3) = 32.065+3(15.999) = 80.062 g/mol</p><p>%S = 32.065÷80.062×100 = <strong>40.05%</strong></p>'},
  {id:'p29', difficulty:'easy', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of chlorine in calcium chloride (CaCl2)?', answer:63.89, unit:'%', tolerance:0.3, solution:'<p>Use % by mass = (mass of element ÷ molar mass) × 100.</p><p>M(CaCl2) = 40.078+2(35.453) = 110.984 g/mol</p><p>%Cl = 70.906÷110.984×100 = <strong>63.89%</strong></p>'},
  {id:'p30', difficulty:'easy', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of oxygen in potassium permanganate (KMnO4)?', answer:40.50, unit:'%', tolerance:0.3, solution:'<p>Use % by mass = (mass of element ÷ molar mass) × 100.</p><p>M(KMnO4) = 39.098+54.938+4(15.999) = 158.032 g/mol</p><p>%O = 63.996÷158.032×100 = <strong>40.50%</strong></p>'},
  {id:'p31', difficulty:'medium', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of nitrogen in urea, (NH2)2CO?', answer:46.65, unit:'%', tolerance:0.3, solution:'<p>Use % by mass = (mass of element ÷ molar mass) × 100.</p><p>M(urea) = 2(14.007)+4(1.008)+12.011+15.999 = 60.056 g/mol</p><p>%N = 28.014÷60.056×100 = <strong>46.65%</strong></p>'},
  {id:'p32', difficulty:'easy', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of manganese in MnO2?', answer:63.19, unit:'%', tolerance:0.3, solution:'<p>Use % by mass = (mass of element ÷ molar mass) × 100.</p><p>M(MnO2) = 54.938+2(15.999) = 86.936 g/mol</p><p>%Mn = 54.938÷86.936×100 = <strong>63.19%</strong></p>'},

  // Gases at STP
  {id:'p33', difficulty:'easy', type:'calc', tag:'Gas at STP', q:'What volume does 4.50 mol of O2 occupy at STP?', answer:100.86, unit:'L', tolerance:0.5, solution:'<p>V = n × 22.414 L/mol = 4.50 × 22.414 = <strong>100.86 L</strong></p>'},
  {id:'p34', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'A sample of CH4 occupies 11.2 L at STP. How many molecules is this?', answer:3.009e23, unit:'molecules', tolerance:5e21, solution:'<p>mol = 11.2 ÷ 22.414 = 0.4997 mol<br>N = 0.4997 × 6.022×10^23 = <strong>3.01 × 10^23 molecules</strong></p>'},
  {id:'p35', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'What volume at STP does 4.40 g of propane (C3H8) occupy?', answer:2.237, unit:'L', tolerance:0.05, solution:'<p>M(C3H8) = 3(12.011)+8(1.008) = 44.097 g/mol<br>mol = 4.40÷44.097 = 0.09978 mol<br>V = 0.09978 × 22.414 = <strong>2.237 L</strong></p>'},
  {id:'p36', difficulty:'easy', type:'calc', tag:'Gas at STP', q:'How many moles of gas are in 3.20 L at STP?', answer:0.1428, unit:'mol', tolerance:0.003, solution:'<p>n = V ÷ 22.414 L/mol = 3.20 ÷ 22.414 = <strong>0.1428 mol</strong></p>'},
  {id:'p37', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'What volume at STP does 88.0 g of CO2 occupy?', answer:44.82, unit:'L', tolerance:0.3, solution:'<p>M(CO2) = 12.011+2(15.999) = 44.009 g/mol<br>mol = 88.0÷44.009 = 1.9996 mol<br>V = 1.9996 × 22.414 = <strong>44.82 L</strong></p>'},
  {id:'p38', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'How many argon atoms are in a 3.00 L sample of Ar gas at STP?', answer:8.060e22, unit:'Ar atoms', tolerance:5e20, solution:'<p>mol Ar = 3.00÷22.414 = 0.13384 mol<br>N = 0.13384 × 6.022×10^23 = <strong>8.06 × 10^22 atoms</strong></p>'},
  {id:'p39', difficulty:'easy', type:'calc', tag:'Gas at STP', q:'What volume does 0.350 mol of Cl2 gas occupy at STP?', answer:7.845, unit:'L', tolerance:0.05, solution:'<p>V = 0.350 × 22.414 = <strong>7.845 L</strong></p>'},

  // Empirical formulas
  {id:'p40', difficulty:'medium', type:'calc', tag:'Empirical Formula', q:'A compound is 40.0% C, 6.71% H, and 53.3% O by mass. What is the empirical formula?', answer:'CH2O', unit:'', tolerance:0, isText:true, solution:'<p>Assume 100 g: 40.0 g C, 6.71 g H, 53.3 g O<br>mol C = 40.0÷12.011 = 3.330; mol H = 6.71÷1.008 = 6.657; mol O = 53.3÷15.999 = 3.331<br>Divide by 3.330 → 1:2:1 → <strong>CH2O</strong></p>'},
  {id:'p41', difficulty:'medium', type:'calc', tag:'Empirical Formula', q:'A compound is 52.2% C, 13.0% H, and 34.8% O by mass. What is the empirical formula?', answer:'C2H6O', unit:'', tolerance:0, isText:true, solution:'<p>mol C = 52.2÷12.011 = 4.346; mol H = 13.0÷1.008 = 12.897; mol O = 34.8÷15.999 = 2.175<br>Divide by 2.175 → C:1.997 H:5.930 O:1.000 → ratio 2:6:1 → <strong>C2H6O</strong></p>'},
  {id:'p42', difficulty:'medium', type:'calc', tag:'Empirical Formula', q:'A compound contains only C and H: 75.0% C and 25.0% H. What is the empirical formula?', answer:'CH4', unit:'', tolerance:0, isText:true, solution:'<p>mol C = 75.0÷12.011 = 6.244; mol H = 25.0÷1.008 = 24.802<br>Divide by 6.244 → C:1.000 H:3.972 ≈ 1:4 → <strong>CH4</strong></p>'},

  // Counting atoms
  {id:'p43', difficulty:'easy', type:'calc', tag:'Counting Atoms', q:'How many moles of carbon atoms are in 1.00 mol of citric acid (C6H8O7)?', answer:6.00, unit:'mol C', tolerance:0.01, solution:'<p>Each molecule has 6 carbon atoms → 1.00 mol compound contains <strong>6.00 mol carbon atoms</strong></p>'},
  {id:'p44', difficulty:'medium', type:'calc', tag:'Counting Atoms', q:'How many sodium ions (Na^+) are present in 58.44 g of sodium chloride (NaCl)?', answer:6.022e23, unit:'Na^+ ions', tolerance:5e21, solution:'<p>mol NaCl = 58.44÷58.443 = 1.000 mol<br>Each formula unit gives 1 Na^+ → <strong>6.022 × 10^23 Na^+ ions</strong></p>'},
  {id:'p45', difficulty:'easy', type:'calc', tag:'Counting Atoms', q:'How many moles of oxygen atoms are in 2.50 mol of Al2(SO4)3?', answer:30.0, unit:'mol O', tolerance:0.1, solution:'<p>Al2(SO4)3 has 3 × 4 = 12 oxygen atoms per formula unit<br>2.50 mol × 12 = <strong>30.0 mol O atoms</strong></p>'},
  {id:'p46', difficulty:'medium', type:'calc', tag:'Counting Atoms', q:'How many atoms of hydrogen are in 1.00 mol of C6H12O6 (glucose)?', answer:7.226e24, unit:'H atoms', tolerance:5e22, solution:'<p>C6H12O6 has 12 H atoms per molecule<br>1.00 mol × 12 × 6.022×10^23 = <strong>7.226 × 10^24 H atoms</strong></p>'},
  {id:'p47', difficulty:'medium', type:'calc', tag:'Counting Atoms', q:'How many aluminum atoms are in 10.0 g of pure aluminum (Al)?', answer:2.232e23, unit:'Al atoms', tolerance:5e21, solution:'<p>mol Al = 10.0÷26.982 = 0.3706 mol<br>N = 0.3706 × 6.022×10^23 = <strong>2.232 × 10^23 atoms</strong></p>'},

  // ─── CONCEPTUAL (19 problems) ─────────────────────────────────

  {id:'p48', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'Why is the mole defined using carbon-12 specifically, rather than hydrogen-1?', choices:['Hydrogen is too reactive to measure accurately','Carbon-12 was the IUPAC standard that allowed the most precise mass comparisons via mass spectrometry','Carbon is the most abundant element','Hydrogen-1 does not have any neutrons'], correct:1, solution:'<p>Carbon-12 provided the most precise mass standard because of its isotopic purity and measurability via mass spectrometry.</p>'},
  {id:'p49', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'Two samples each contain 1.00 mol of substance. Sample A is NaCl; Sample B is H2O. Which statement is TRUE?', choices:['Sample A has more representative particles','Both samples contain the same number of representative particles','Sample B has more atoms','Sample A has more formula units'], correct:1, solution:'<p>Both contain exactly 6.022×10^23 representative particles (1.00 mol each). For NaCl, those particles are formula units; for H2O, they are molecules. The mole is a counting unit, not a mass unit.</p>'},
  {id:'p50', difficulty:'medium', type:'concept', tag:'Molar Mass', q:'A student calculates a molar mass of 35.5 g/mol for an unknown compound. The actual molar mass is 71.0 g/mol. What is the most likely error?', choices:['They forgot to multiply atomic masses by subscripts','They found the empirical formula mass, not the molecular formula mass','They used the wrong periodic table','They measured volume instead of mass'], correct:1, solution:'<p>The empirical formula mass is exactly half the actual molecular molar mass — the classic error of stopping at the empirical formula.</p>'},
  {id:'p51', difficulty:'medium', type:'concept', tag:'Counting Atoms', q:'Which of the following samples contains the greatest number of oxygen ATOMS?', choices:['1.00 mol of O2','1.00 mol of SO3','1.00 mol of H2O','1.00 mol of CO2'], correct:1, solution:'<p>SO3 has 3 oxygen atoms per molecule, so 1.00 mol SO3 contains 3.00 mol O atoms — more than any other choice.</p>'},
  {id:'p52', difficulty:'medium', type:'concept', tag:'Molecular Formula', q:'The empirical formula of a compound is CH2O and the molar mass is ~180 g/mol. Which molecular formula is correct?', choices:['CH2O','C3H6O3','C6H12O6','C2H4O2'], correct:2, solution:'<p>M(CH2O) = 30.026 g/mol. n = 180÷30.026 ≈ 6. Molecular formula = <strong>C6H12O6</strong>.</p>'},
  {id:'p53', difficulty:'easy', type:'concept', tag:'Molar Mass', q:'What does it mean when we say the molar mass of carbon is 12.011 g/mol rather than exactly 12.000 g/mol?', choices:['The measurement was imprecise','Natural carbon contains a mix of isotopes that average to 12.011','Carbon atoms are not identical to each other','12.000 g/mol refers to diamond specifically'], correct:1, solution:'<p>Periodic table atomic masses are weighted averages of all naturally occurring isotopes in their natural abundances.</p>'},
  {id:'p54', difficulty:'easy', type:'concept', tag:'Gas at STP', q:'A sample of gas at STP occupies 44.8 L. How many moles of gas is this?', choices:['1.00 mol','2.00 mol','22.4 mol','4.00 mol'], correct:1, solution:'<p>At STP, 1 mol = 22.414 L. So 44.8 L ÷ 22.414 = 1.999 ≈ <strong>2.00 mol</strong>.</p>'},
  {id:'p55', difficulty:'medium', type:'concept', tag:'Percent Composition', q:'Compound X and Compound Y have the same empirical formula (CH2) but different molecular formulas. Which property will definitely be different?', choices:['Percent carbon by mass','Percent hydrogen by mass','Molar mass','All of the above'], correct:2, solution:'<p>Same empirical formula → same percent composition by mass. Different molecular formulas → different molar masses.</p>'},
  {id:'p56', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'A chemist calculates that a sample contains 3.011 × 10^23 molecules. This is closest to:', choices:['1/4 mole','1/2 mole','1 mole','2 moles'], correct:1, solution:'<p>3.011×10^23 ÷ 6.022×10^23 = 0.500 mol = <strong>1/2 mole</strong>.</p>'},
  {id:'p57', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'Which of the following is the BEST definition of molar mass?', choices:['The mass of 6.022×10^23 particles in grams','The number of protons plus neutrons in one atom','The ratio of atomic mass to Avogadro\'s number','The mass listed on the periodic table in amu'], correct:0, solution:'<p>Molar mass is the mass of exactly one mole of particles, expressed in g/mol.</p>'},
  {id:'p58', difficulty:'easy', type:'concept', tag:'Counting Atoms', q:'A student has 1.00 mol of NaCl and 1.00 mol of MgCl2. Which sample contains more chloride ions (Cl^-)?', choices:['The NaCl sample','They contain the same number','The MgCl2 sample, because each formula unit releases 2 Cl^-','It depends on the volume of water used'], correct:2, solution:'<p>MgCl2 releases 2 Cl^- per formula unit; NaCl releases only 1. So MgCl2 contains twice as many chloride ions.</p>'},
  {id:'p59', difficulty:'medium', type:'concept', tag:'Molar Mass', q:'Which of these 1.01-gram samples contains the greatest number of atoms?', choices:['1.00 g of iron (Fe)','1.00 g of carbon (C)','1.00 g of lead (Pb)','1.00 g of calcium (Ca)'], correct:1, solution:'<p>Atoms per gram = Nₐ ÷ M. Carbon has the lowest molar mass of these four, so 1.00 g of carbon contains the most atoms.</p>'},
  {id:'p60', difficulty:'medium', type:'concept', tag:'Gas at STP', q:'Two gases, He and O2, each occupy 22.414 L at STP. Which statement is correct?', choices:['Same number of molecules and same mass','Same number of molecules but different masses','Different number of molecules but same mass','Different number of molecules and different masses'], correct:1, solution:'<p>Each contains exactly 1.00 mol = 6.022×10^23 molecules (same count), but He has M=4.003 g/mol and O2 has M=31.998 g/mol (very different masses).</p>'},
  {id:'p61', difficulty:'easy', type:'concept', tag:'Molar Mass', q:'Which 1.01-mol sample has the GREATEST mass?', choices:['1.00 mol of H2O','1.00 mol of NaCl','1.00 mol of Fe','1.00 mol of Pb'], correct:3, solution:'<p>The molar mass determines the mass of 1 mol. Pb: 207.2 g/mol is the largest. <strong>1.00 mol Pb = 207.2 g</strong>.</p>'},
  {id:'p62', difficulty:'medium', type:'concept', tag:'Molecular Formula', q:'A student is given an empirical formula of CH3O and told the molar mass is 62 g/mol. What is the correct molecular formula?', choices:['CH3O','C2H6O2','C3H9O3','CH3O cannot form a compound with that molar mass'], correct:1, solution:'<p>M(CH3O) = 31.034 g/mol. n = 62÷31.034 ≈ 2. Molecular formula = <strong>C2H6O2</strong>.</p>'},
  {id:'p63', difficulty:'medium', type:'concept', tag:'Molar Mass', q:'Which sample contains the fewest molecules?', choices:['1.00 g of H2O','1.00 g of O2','1.00 g of CO2','1.00 g of C6H12O6'], correct:3, solution:'<p>Molecules per gram = Nₐ ÷ M. C6H12O6 has the largest molar mass (180.156), so 1.00 g contains the fewest molecules.</p>'},
  {id:'p64', difficulty:'easy', type:'concept', tag:'Counting Atoms', q:'2 mol of H2O and 1 mol of H2O2 — which contains more hydrogen ATOMS?', choices:['2 mol H2O, because it has more molecules','1 mol H2O2, because hydrogen peroxide is more reactive','They contain the same number of hydrogen atoms','Cannot be determined without knowing temperature'], correct:0, solution:'<p>2 mol H2O × 2 H per molecule = 4 mol H. 1 mol H2O2 × 2 H per molecule = 2 mol H. <strong>2 mol H2O has more H atoms.</strong></p>'},
  {id:'p65', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'Why can you NOT convert directly from grams to number of particles in a single step?', choices:['You can — just divide grams by Avogadro\'s number','Grams measure mass; particles are counted by moles. You must convert to moles first as the intermediate unit','Avogadro\'s number only applies to gases','The periodic table does not give enough information'], correct:1, solution:'<p>The mole is the mandatory bridge. Grams ÷ molar mass → moles, then moles × Nₐ → particles. No direct path exists.</p>'},
  {id:'p66', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'Which statement about Avogadro\'s number is FALSE?', choices:['It equals approximately 6.022 × 10^23','It is the number of atoms in exactly 12 g of carbon-12','It has units of mol^-1','It changes depending on the substance being measured'], correct:3, solution:'<p>Avogadro\'s number is a universal constant — 6.022×10^23 mol^-1 — and does not change based on the substance.</p>'},

  // ─── MULTI-STEP (15 problems) ─────────────────────────────────

  {id:'p67', difficulty:'hard', type:'multi', tag:'Empirical Formula', q:'A student burns 0.500 g of a hydrocarbon (C and H only) and collects 1.572 g CO2 and 0.644 g H2O. What is the empirical formula?', answer:'CH2', unit:'', isText:true, tolerance:0, solution:'<p>mol C = 1.572÷44.009 = 0.03572; mol H = (0.644÷18.015)×2 = 0.07149</p><p>Divide by 0.03572 → C:1.000 H:2.001 → <strong>CH2</strong></p>'},
  {id:'p68', difficulty:'medium', type:'multi', tag:'Counting Atoms', q:'How many atoms of hydrogen are in 50.0 g of sucrose (C12H22O11, M = 342.30 g/mol)?', answer:1.935e24, unit:'H atoms', tolerance:5e22, solution:'<p>mol sucrose = 50.0÷342.30 = 0.14608 mol<br>mol H = 0.14608×22 = 3.2138 mol<br>atoms H = 3.2138 × 6.022×10^23 = <strong>1.935 × 10^24</strong></p>'},
  {id:'p69', difficulty:'medium', type:'multi', tag:'Counting Atoms', q:'Iron(III) oxide (Fe2O3, M = 159.687 g/mol) — how many iron atoms are in 50.0 g of Fe2O3?', answer:3.771e23, unit:'Fe atoms', tolerance:5e21, solution:'<p>mol Fe2O3 = 50.0÷159.687 = 0.31310 mol<br>mol Fe = 0.31310×2 = 0.62620 mol<br>atoms Fe = 0.62620 × 6.022×10^23 = <strong>3.771 × 10^23</strong></p>'},
  {id:'p70', difficulty:'medium', type:'multi', tag:'Gas at STP', q:'A gas sample contains 4.00 × 10^23 molecules of N2 and 2.00 × 10^23 molecules of O2. What is the total volume of the mixture at STP?', answer:22.33, unit:'L', tolerance:0.2, solution:'<p>mol N2 = 4.00×10^23÷6.022×10^23 = 0.6643 mol<br>mol O2 = 2.00×10^23÷6.022×10^23 = 0.3321 mol<br>total mol = 0.9964; V = 0.9964 × 22.414 = <strong>22.33 L</strong></p>'},
  {id:'p71', difficulty:'medium', type:'multi', tag:'Percent Composition', q:'What is the percent composition of each element in aspirin (C9H8O4, M = 180.159 g/mol)?', answer:'%C=60.0, %H=4.48, %O=35.5', unit:'', isText:true, tolerance:0, solution:'<p>%C = 9(12.011)÷180.159×100 = <strong>60.00%</strong><br>%H = 8(1.008)÷180.159×100 = <strong>4.476%</strong><br>%O = 4(15.999)÷180.159×100 = <strong>35.52%</strong></p>'},
  {id:'p72', difficulty:'hard', type:'multi', tag:'Molecular Formula', q:'A compound contains 38.7% C, 9.68% H, and 51.6% O by mass. Its molar mass is ~62 g/mol. Determine the molecular formula.', answer:'C2H6O2', unit:'', isText:true, tolerance:0, solution:'<p>Assume a 100 g sample so the percentages become grams, then convert each element to moles.</p><p>mol C = 38.7 ÷ 12.011 = 3.222; mol H = 9.68 ÷ 1.008 = 9.603; mol O = 51.6 ÷ 15.999 = 3.225</p><p>Divide by the smallest value, 3.222, to get the ratio 1 : 3 : 1, so the empirical formula is CH3O.</p><p>M(CH3O) = 31.034 g/mol, and 62 ÷ 31.034 ≈ 2. Multiply the subscripts by 2 to get <strong>C2H6O2</strong>.</p>'},
  {id:'p73', difficulty:'medium', type:'multi', tag:'Mol–Particles', q:'If a 2.50 mol sample of H2SO4 fully dissociates (H2SO4 → 2H^+ + SO4^2-), how many total ions result?', answer:4.517e24, unit:'ions', tolerance:1e23, solution:'<p>2.50 mol H2SO4 → 5.00 mol H^+ + 2.50 mol SO4^2- = 7.50 mol total ions<br>N = 7.50 × 6.022×10^23 = <strong>4.517 × 10^24 ions</strong></p>'},
  {id:'p74', difficulty:'medium', type:'multi', tag:'Molecular Formula', q:'A compound has the empirical formula CH2O and a molar mass of 60.05 g/mol. What is the molecular formula?', answer:'C2H4O2', unit:'', isText:true, tolerance:0, solution:'<p>M(CH2O) = 12.011+2(1.008)+15.999 = 30.026 g/mol<br>n = 60.05÷30.026 = 1.999 ≈ 2 → <strong>C2H4O2</strong></p>'},
  {id:'p75', difficulty:'hard', type:'multi', tag:'Empirical Formula', q:'A hydrate of copper(II) sulfate has the formula CuSO4·xH2O. A 4.976 g sample is heated to drive off all water, leaving 3.184 g of anhydrous CuSO4. Find x.', answer:'5', unit:'', isText:true, tolerance:0, solution:'<p>mass H2O lost = 4.976-3.184 = 1.792 g<br>mol CuSO4 = 3.184÷159.607 = 0.019949 mol<br>mol H2O = 1.792÷18.015 = 0.09947 mol<br>x = 0.09947÷0.019949 = <strong>4.986 ≈ 5</strong></p>'},
  {id:'p76', difficulty:'medium', type:'multi', tag:'Molar Mass', q:'A 5.00 g sample of an unknown pure element contains 1.327 × 10^23 atoms. Identify the element.', answer:'Sodium', unit:'', isText:true, tolerance:0, solution:'<p>mol = 1.327×10^23÷6.022×10^23 = 0.2204 mol<br>M = 5.00÷0.2204 = <strong>22.69 g/mol ≈ sodium (Na, M=22.990)</strong></p>'},
  {id:'p77', difficulty:'medium', type:'multi', tag:'Mol–Particles', q:'Magnesium (Mg, M = 24.305 g/mol) reacts with O2 to form MgO. Starting with 3.60 g of Mg, how many formula units of MgO could theoretically be produced?', answer:8.920e22, unit:'formula units MgO', tolerance:5e20, solution:'<p>mol Mg = 3.60÷24.305 = 0.14813 mol → 0.14813 mol MgO (1:1 ratio)<br>formula units = 0.14813 × 6.022×10^23 = <strong>8.920 × 10^22 formula units</strong></p>'},
  {id:'p78', difficulty:'medium', type:'multi', tag:'Counting Atoms', q:'How many oxygen atoms are in 34.0 g of hydrogen peroxide (H2O2, M = 34.014 g/mol)?', answer:1.204e24, unit:'O atoms', tolerance:5e22, solution:'<p>mol H2O2 = 34.0÷34.014 = 0.99959 mol ≈ 1.000 mol<br>mol O = 1.000×2 = 2.000 mol (2 O per H2O2)<br>atoms O = 2.000 × 6.022×10^23 = <strong>1.204 × 10^24 O atoms</strong></p>'},
  {id:'p79', difficulty:'medium', type:'multi', tag:'Counting Atoms', q:'What is the mass of chlorine atoms in 25.0 g of AlCl3 (M = 133.341 g/mol)?', answer:19.94, unit:'g Cl', tolerance:0.15, solution:'<p>mol AlCl3 = 25.0÷133.341 = 0.18749 mol<br>mol Cl = 0.18749×3 = 0.56246 mol<br>mass Cl = 0.56246 × 35.453 = <strong>19.94 g Cl</strong></p>'},
  {id:'p80', difficulty:'hard', type:'multi', tag:'Molecular Formula', q:'A compound contains 85.6% C and 14.4% H by mass. Its molar mass is approximately 42 g/mol. Find the molecular formula.', answer:'C3H6', unit:'', isText:true, tolerance:0, solution:'<p>mol C = 85.6÷12.011 = 7.127; mol H = 14.4÷1.008 = 14.286<br>Divide by 7.127 → C:1.000 H:2.005 → empirical CH2; M(CH2)=14.027<br>n = 42÷14.027 = 2.994 ≈ 3 → <strong>C3H6</strong></p>'},
  {id:'p81', difficulty:'medium', type:'multi', tag:'Counting Atoms', q:'How many total atoms are in 10.0 g of calcium phosphate, Ca3(PO4)2 (M = 310.174 g/mol)?', answer:2.524e23, unit:'total atoms', tolerance:5e21, solution:'<p>mol Ca3(PO4)2 = 10.0÷310.174 = 0.032240 mol<br>Atoms per formula unit: 3 Ca + 2 P + 8 O = 13 atoms<br>mol atoms = 0.032240×13 = 0.41912 mol<br>N = 0.41912 × 6.022×10^23 = <strong>2.524 × 10^23 total atoms</strong></p>'},

  // ─── EXPANSION BATCH — 60 problems (20 easy / 25 medium / 15 hard) ─────────────

  // ── EASY (20) ──
  {id:'p82', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'How many moles are in 36.0 g of water (H2O)?', answer:1.998, unit:'mol', tolerance:0.02, solution:'<p>M(H2O) = 18.015 g/mol. n = m ÷ M = 36.0 ÷ 18.015 = <strong>1.998 mol</strong></p>'},
  {id:'p83', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'What is the mass of 2.00 mol of NaCl?', answer:116.9, unit:'g', tolerance:0.5, solution:'<p>M(NaCl) = 58.443 g/mol. m = n × M = 2.00 × 58.443 = <strong>116.9 g</strong></p>'},
  {id:'p84', difficulty:'easy', type:'calc', tag:'Mol–Particles', q:'How many molecules are in 1.00 mol of CO2?', answer:6.022e23, unit:'molecules', tolerance:5e21, solution:'<p>By definition, 1 mole of any substance contains exactly Avogadro\'s number of particles: <strong>6.022 × 10^23 molecules</strong>.</p>'},
  {id:'p85', difficulty:'easy', type:'calc', tag:'Mol–Particles', q:'How many moles are in 1.806 × 10^24 atoms of carbon?', answer:2.999, unit:'mol', tolerance:0.02, solution:'<p>n = N ÷ Nₐ = 1.806×10^24 ÷ 6.022×10^23 = <strong>2.999 mol ≈ 3.00 mol</strong></p>'},
  {id:'p86', difficulty:'easy', type:'calc', tag:'Molar Mass', q:'What is the molar mass of NaOH?', answer:39.997, unit:'g/mol', tolerance:0.05, solution:'<p>22.990 + 15.999 + 1.008 = <strong>39.997 g/mol</strong></p>'},
  {id:'p87', difficulty:'easy', type:'calc', tag:'Molar Mass', q:'What is the molar mass of CaCO3?', answer:100.086, unit:'g/mol', tolerance:0.1, solution:'<p>40.078 + 12.011 + 3(15.999) = 40.078+12.011+47.997 = <strong>100.086 g/mol</strong></p>'},
  {id:'p88', difficulty:'easy', type:'calc', tag:'Gas at STP', q:'What volume does 2.00 mol of N2 occupy at STP?', answer:44.828, unit:'L', tolerance:0.3, solution:'<p>V = n × 22.414 L/mol = 2.00 × 22.414 = <strong>44.83 L</strong></p>'},
  {id:'p89', difficulty:'easy', type:'calc', tag:'Gas at STP', q:'How many moles are in 11.2 L of gas at STP?', answer:0.4997, unit:'mol', tolerance:0.01, solution:'<p>n = V ÷ 22.414 = 11.2 ÷ 22.414 = <strong>0.4997 mol ≈ 0.500 mol</strong></p>'},
  {id:'p90', difficulty:'easy', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of hydrogen in H2O?', answer:11.19, unit:'%', tolerance:0.1, solution:'<p>%H = 2(1.008) ÷ 18.015 × 100 = 2.016÷18.015×100 = <strong>11.19%</strong></p>'},
  {id:'p91', difficulty:'easy', type:'calc', tag:'Counting Atoms', q:'How many moles of atoms are in 1.00 mol of CO2?', answer:3.00, unit:'mol atoms', tolerance:0.01, solution:'<p>CO2 has 1+2 = 3 atoms per molecule. 1.00 mol × 3 = <strong>3.00 mol atoms</strong></p>'},
  {id:'p92', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'Avogadro\'s number is approximately:', choices:['6.022 × 10^23', '3.14 × 10^8', '9.11 × 10^-31', '1.00 × 10^0'], correct:0, solution:'<p>Avogadro\'s number, 6.022 × 10^23 per mole, is the number of representative particles in exactly one mole of any substance.</p>'},
  {id:'p93', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'Which quantity is directly proportional to the number of moles of a substance?', choices:['Mass', 'Number of particles', 'Volume at STP (for a gas)', 'All of the above'], correct:3, solution:'<p>All three scale directly with moles: mass = n × M, particles = n × Nₐ, and gas volume at STP = n × 22.414 L. The mole is the central hub connecting all of them.</p>'},
  {id:'p94', difficulty:'easy', type:'concept', tag:'Gas at STP', q:'One mole of any gas at STP occupies approximately:', choices:['22.4 L', '1.00 L', '6.022 × 10^23 L', '100.0 L'], correct:0, solution:'<p>The molar volume of an ideal gas at STP (0°C, 1 atm) is 22.414 L/mol, regardless of which gas it is.</p>'},
  {id:'p95', difficulty:'easy', type:'concept', tag:'Molar Mass', q:'The molar mass of an element, in g/mol, is numerically equal to its:', choices:['Atomic mass in amu', 'Atomic number', 'Number of neutrons', 'Number of valence electrons'], correct:0, solution:'<p>An element\'s atomic mass in amu (from the periodic table) and its molar mass in g/mol share the exact same number — this connection is what makes the mole concept so useful.</p>'},
  {id:'p96', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'What is the mass of 0.250 mol of KCl?', answer:18.64, unit:'g', tolerance:0.1, solution:'<p>M(KCl) = 39.098+35.453 = 74.551 g/mol. m = 0.250 × 74.551 = <strong>18.64 g</strong></p>'},
  {id:'p97', difficulty:'easy', type:'calc', tag:'Molar Mass', q:'What is the molar mass of MgCl2?', answer:95.211, unit:'g/mol', tolerance:0.1, solution:'<p>24.305 + 2(35.453) = 24.305+70.906 = <strong>95.211 g/mol</strong></p>'},
  {id:'p98', difficulty:'easy', type:'calc', tag:'Mol–Particles', q:'How many moles are in 6.022 × 10^22 molecules of any substance?', answer:0.1000, unit:'mol', tolerance:0.002, solution:'<p>n = N ÷ Nₐ = 6.022×10^22 ÷ 6.022×10^23 = <strong>0.1000 mol</strong></p>'},
  {id:'p99', difficulty:'easy', type:'concept', tag:'Mole Concept', q:'Which of the following contains exactly 1 mole of atoms?', choices:['6.022 × 10^23 atoms of any element', '1.00 g of any element', '1.00 L of any element', 'The atomic mass of any element in kg'], correct:0, solution:'<p>By definition, 1 mole of anything — atoms, molecules, ions — contains exactly 6.022 × 10^23 representative particles.</p>'},
  {id:'p100', difficulty:'easy', type:'calc', tag:'Gram–Mol', q:'What is the mass of 1.00 mol of oxygen gas (O2)?', answer:31.998, unit:'g', tolerance:0.05, solution:'<p>M(O2) = 2(15.999) = <strong>31.998 g/mol</strong>, so 1.00 mol has a mass of 31.998 g.</p>'},
  {id:'p101', difficulty:'easy', type:'calc', tag:'Counting Atoms', q:'How many total atoms are in 1.00 mol of NH3?', answer:4.00, unit:'mol atoms', tolerance:0.01, solution:'<p>NH3 has 1+3 = 4 atoms per molecule. 1.00 mol × 4 = <strong>4.00 mol atoms</strong></p>'},

  // ── MEDIUM (25) ──
  {id:'p102', difficulty:'medium', type:'calc', tag:'Gram–Mol', q:'How many moles are in 250.0 g of iron(III) oxide (Fe2O3)?', answer:1.566, unit:'mol', tolerance:0.02, solution:'<p>M(Fe2O3) = 2(55.845)+3(15.999) = 159.687 g/mol. n = 250.0÷159.687 = <strong>1.566 mol</strong></p>'},
  {id:'p103', difficulty:'medium', type:'calc', tag:'Mol–Particles', q:'How many molecules are in 25.0 g of ammonia (NH3)?', answer:8.840e23, unit:'molecules', tolerance:5e21, solution:'<p>M(NH3) = 17.031 g/mol. mol = 25.0÷17.031 = 1.4679 mol. N = 1.4679 × 6.022×10^23 = <strong>8.840 × 10^23 molecules</strong></p>'},
  {id:'p104', difficulty:'medium', type:'calc', tag:'Mol–Particles', q:'What is the mass of 3.011 × 10^23 molecules of ethanol (C2H5OH, M = 46.069 g/mol)?', answer:23.03, unit:'g', tolerance:0.2, solution:'<p>mol = 3.011×10^23÷6.022×10^23 = 0.5000 mol. m = 0.5000 × 46.069 = <strong>23.03 g</strong></p>'},
  {id:'p105', difficulty:'medium', type:'calc', tag:'Molar Mass', q:'What is the molar mass of Al(OH)3?', answer:78.003, unit:'g/mol', tolerance:0.1, solution:'<p>26.982 + 3(15.999) + 3(1.008) = 26.982+47.997+3.024 = <strong>78.003 g/mol</strong></p>'},
  {id:'p106', difficulty:'medium', type:'calc', tag:'Molar Mass', q:'What is the molar mass of ammonium carbonate, (NH4)2CO3?', answer:96.086, unit:'g/mol', tolerance:0.1, solution:'<p>2(14.007)+8(1.008)+12.011+3(15.999) = 28.014+8.064+12.011+47.997 = <strong>96.086 g/mol</strong></p>'},
  {id:'p107', difficulty:'medium', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of oxygen in carbon dioxide (CO2)?', answer:72.71, unit:'%', tolerance:0.3, solution:'<p>M(CO2) = 44.009 g/mol. %O = 2(15.999)÷44.009×100 = 31.998÷44.009×100 = <strong>72.71%</strong></p>'},
  {id:'p108', difficulty:'medium', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of sodium in sodium carbonate (Na2CO3)?', answer:43.38, unit:'%', tolerance:0.3, solution:'<p>M(Na2CO3) = 105.988 g/mol. %Na = 2(22.990)÷105.988×100 = 45.980÷105.988×100 = <strong>43.38%</strong></p>'},
  {id:'p109', difficulty:'medium', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of calcium in calcium phosphate, Ca3(PO4)2?', answer:38.76, unit:'%', tolerance:0.3, solution:'<p>M(Ca3(PO4)2) = 310.174 g/mol. %Ca = 3(40.078)÷310.174×100 = 120.234÷310.174×100 = <strong>38.76%</strong></p>'},
  {id:'p110', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'What volume at STP does 12.5 g of CH4 occupy?', answer:17.46, unit:'L', tolerance:0.15, solution:'<p>M(CH4) = 16.043 g/mol. mol = 12.5÷16.043 = 0.7791 mol. V = 0.7791 × 22.414 = <strong>17.46 L</strong></p>'},
  {id:'p111', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'How many moles of gas are in 5.60 L at STP?', answer:0.2498, unit:'mol', tolerance:0.005, solution:'<p>n = V ÷ 22.414 = 5.60÷22.414 = <strong>0.2498 mol</strong></p>'},
  {id:'p112', difficulty:'medium', type:'calc', tag:'Counting Atoms', q:'How many atoms are in 15.0 g of aluminum (Al)?', answer:3.348e23, unit:'Al atoms', tolerance:5e21, solution:'<p>M(Al) = 26.982 g/mol. mol = 15.0÷26.982 = 0.5558 mol. N = 0.5558 × 6.022×10^23 = <strong>3.348 × 10^23 atoms</strong></p>'},
  {id:'p113', difficulty:'medium', type:'calc', tag:'Counting Atoms', q:'How many moles of chlorine atoms are in 2.50 mol of MgCl2?', answer:5.00, unit:'mol Cl', tolerance:0.02, solution:'<p>Each MgCl2 formula unit has 2 Cl atoms. 2.50 mol × 2 = <strong>5.00 mol Cl atoms</strong></p>'},
  {id:'p114', difficulty:'medium', type:'calc', tag:'Percent Composition', q:'How many grams of nitrogen are in 50.0 g of ammonium nitrate (NH4NO3)?', answer:17.50, unit:'g N', tolerance:0.2, solution:'<p>M(NH4NO3) = 80.043 g/mol; 2 N: 28.014 g/mol. %N = 28.014÷80.043×100 = 35.00%. mass N = 0.3500 × 50.0 = <strong>17.50 g</strong></p>'},
  {id:'p115', difficulty:'medium', type:'calc', tag:'Empirical Formula', q:'A compound is 82.4% N and 17.6% H by mass. What is the empirical formula?', answer:'NH3', unit:'', tolerance:0, isText:true, solution:'<p>mol N = 82.4÷14.007 = 5.882; mol H = 17.6÷1.008 = 17.46<br>Divide by 5.882 → N:1.000 H:2.968 ≈ 1:3 → <strong>NH3</strong></p>'},
  {id:'p116', difficulty:'medium', type:'calc', tag:'Empirical Formula', q:'A compound is 30.4% N and 69.6% O by mass. What is the empirical formula?', answer:'NO2', unit:'', tolerance:0, isText:true, solution:'<p>mol N = 30.4÷14.007 = 2.170; mol O = 69.6÷15.999 = 4.350<br>Divide by 2.170 → N:1.000 O:2.005 ≈ 1:2 → <strong>NO2</strong></p>'},
  {id:'p117', difficulty:'medium', type:'concept', tag:'Molar Mass', q:'Which of these 1.00 g samples contains the greatest number of molecules?', choices:['1.00 g of H2O', '1.00 g of NH3', '1.00 g of CH4', '1.00 g of C6H12O6'], correct:2, solution:'<p>Molecules per gram = Nₐ ÷ M — the lightest molar mass wins. CH4 (16.043 g/mol) has the lowest molar mass of these four, so 1.00 g of it contains the most molecules.</p>'},
  {id:'p118', difficulty:'medium', type:'concept', tag:'Molecular Formula', q:'Two compounds share the empirical formula CH, but Compound X has a molar mass of 78 g/mol and Compound Y has a molar mass of 26 g/mol. What can you conclude?', choices:['X is C6H6 (multiplier 6) and Y is CH (multiplier 1) — they are different molecular formulas built from the same simplest ratio', 'X and Y must be the exact same compound', 'Y cannot exist because its molar mass is too low', 'The empirical formula tells you the exact molecular formula directly'], correct:0, solution:'<p>Empirical formula mass of CH ≈ 13.02 g/mol. For X: 78÷13.02 ≈ 6, giving C6H6 (benzene). For Y: 26÷13.02 ≈ 2, giving C2H2 (acetylene). Same ratio, different actual molecules.</p>'},
  {id:'p119', difficulty:'medium', type:'concept', tag:'Mole Concept', q:'Sample A is 1.00 mol of NaCl; Sample B is 1.00 mol of MgCl2. Which statement is TRUE?', choices:['Both samples contain the same number of formula units, but Sample B contains more total ions overall', 'Sample A contains more formula units', 'Sample B has fewer chloride ions than Sample A', 'They contain the same number of every type of ion'], correct:0, solution:'<p>Both samples contain exactly 6.022×10^23 formula units (1.00 mol each). But each MgCl2 unit releases 3 ions (1 Mg^2+ + 2 Cl^-) versus NaCl\'s 2 ions (1 Na^+ + 1 Cl^-), so Sample B has more total ions overall.</p>'},
  {id:'p120', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'What volume does 0.750 mol of Cl2 gas occupy at STP?', answer:16.81, unit:'L', tolerance:0.1, solution:'<p>V = 0.750 × 22.414 = <strong>16.81 L</strong></p>'},
  {id:'p121', difficulty:'medium', type:'calc', tag:'Counting Atoms', q:'How many moles of atoms are in 2.00 mol of phosphoric acid (H3PO4)?', answer:16.00, unit:'mol atoms', tolerance:0.02, solution:'<p>H3PO4 has 3+1+4 = 8 atoms per molecule. 2.00 mol × 8 = <strong>16.00 mol atoms</strong></p>'},
  {id:'p122', difficulty:'medium', type:'calc', tag:'Percent Composition', q:'How many grams of bromine are in 20.0 g of calcium bromide (CaBr2)?', answer:15.99, unit:'g Br', tolerance:0.15, solution:'<p>M(CaBr2) = 40.078+2(79.904) = 199.886 g/mol. %Br = 159.808÷199.886×100 = 79.95%. mass Br = 0.7995 × 20.0 = <strong>15.99 g</strong></p>'},
  {id:'p123', difficulty:'medium', type:'calc', tag:'Counting Atoms', q:'How many moles of oxygen atoms are in 3.00 mol of Fe2(SO4)3?', answer:36.0, unit:'mol O', tolerance:0.1, solution:'<p>Fe2(SO4)3 has 3 sulfate groups × 4 O = 12 oxygen atoms per formula unit. 3.00 mol × 12 = <strong>36.0 mol O atoms</strong></p>'},
  {id:'p124', difficulty:'medium', type:'calc', tag:'Mol–Particles', q:'How many molecules are in 7.50 g of carbon monoxide (CO)?', answer:1.612e23, unit:'molecules', tolerance:5e21, solution:'<p>M(CO) = 28.010 g/mol. mol = 7.50÷28.010 = 0.2678 mol. N = 0.2678 × 6.022×10^23 = <strong>1.612 × 10^23 molecules</strong></p>'},
  {id:'p125', difficulty:'medium', type:'calc', tag:'Percent Composition', q:'What is the percent by mass of sulfur in aluminum sulfate, Al2(SO4)3?', answer:28.12, unit:'%', tolerance:0.3, solution:'<p>M(Al2(SO4)3) = 342.147 g/mol; 3 S: 3(32.065) = 96.195 g/mol. %S = 96.195÷342.147×100 = <strong>28.12%</strong></p>'},
  {id:'p126', difficulty:'medium', type:'calc', tag:'Gas at STP', q:'What volume at STP does 3.20 g of helium gas (He) occupy?', answer:17.92, unit:'L', tolerance:0.15, solution:'<p>M(He) = 4.003 g/mol. mol = 3.20÷4.003 = 0.7994 mol. V = 0.7994 × 22.414 = <strong>17.92 L</strong></p>'},

  // ── HARD (15) ──
  {id:'p127', difficulty:'hard', type:'multi', tag:'Empirical Formula', q:'A student burns 0.300 g of a hydrocarbon (C and H only) and collects 0.880 g CO2 and 0.540 g H2O. What is the empirical formula?', answer:'CH3', unit:'', tolerance:0, isText:true, solution:'<p>mol C = 0.880÷44.009 = 0.02000 mol. mol H = (0.540÷18.015)×2 = 0.05995 mol.<br>Divide by 0.02000 → C:1.00 H:3.00 → <strong>CH3</strong> (the actual molecule, ethane C2H6, is double this empirical formula).</p>'},
  {id:'p128', difficulty:'hard', type:'multi', tag:'Hydrates', q:'A hydrate of magnesium sulfate, MgSO4·xH2O, has a total mass of 4.929 g. After heating to drive off all the water, only 2.407 g of anhydrous MgSO4 remains. Find x.', answer:'7', unit:'', tolerance:0, isText:true, solution:'<p>mass H2O lost = 4.929-2.407 = 2.522 g. mol MgSO4 = 2.407÷120.366 = 0.02000 mol. mol H2O = 2.522÷18.015 = 0.1400 mol.<br>x = 0.1400÷0.02000 = <strong>7.00 ≈ 7</strong> (this is Epsom salt, MgSO4·7H2O).</p>'},
  {id:'p129', difficulty:'hard', type:'multi', tag:'Molecular Formula', q:'A compound is 54.53% C, 9.15% H, and 36.32% O by mass, with a molar mass of approximately 88.1 g/mol. Find the molecular formula.', answer:'C4H8O2', unit:'', tolerance:0, isText:true, solution:'<p>mol C = 54.53÷12.011 = 4.540; mol H = 9.15÷1.008 = 9.077; mol O = 36.32÷15.999 = 2.270<br>Divide by 2.270 → C:2.00 H:4.00 O:1.00 → empirical C2H4O, M = 44.05 g/mol.<br>n = 88.1÷44.05 ≈ 2 → <strong>C4H8O2</strong></p>'},
  {id:'p130', difficulty:'hard', type:'multi', tag:'Gas at STP', q:'A container holds a mixture of 3.50 g of CH4 and 2.20 g of CO2. What total volume does this mixture occupy at STP?', answer:6.010, unit:'L', tolerance:0.1, solution:'<p>mol CH4 = 3.50÷16.043 = 0.2182 mol. mol CO2 = 2.20÷44.009 = 0.05000 mol.<br>Total mol = 0.2682. V = 0.2682 × 22.414 = <strong>6.01 L</strong></p>'},
  {id:'p131', difficulty:'hard', type:'multi', tag:'Molar Mass', q:'A 6.00 g sample of an unknown pure element contains 1.487 × 10^23 atoms. Identify the element.', answer:'Magnesium', unit:'', tolerance:0, isText:true, solution:'<p>mol = 1.487×10^23÷6.022×10^23 = 0.2469 mol. M = 6.00÷0.2469 = <strong>24.3 g/mol ≈ magnesium (Mg, M=24.305)</strong></p>'},
  {id:'p132', difficulty:'hard', type:'multi', tag:'Percent Composition', q:'What is the percent composition of each element in calcium nitrate, Ca(NO3)2 (M = 164.086 g/mol)?', answer:'%Ca=24.42, %N=17.07, %O=58.50', unit:'', tolerance:0, isText:true, solution:'<p>%Ca = 40.078÷164.086×100 = <strong>24.42%</strong><br>%N = 2(14.007)÷164.086×100 = <strong>17.07%</strong><br>%O = 6(15.999)÷164.086×100 = <strong>58.50%</strong></p>'},
  {id:'p133', difficulty:'hard', type:'multi', tag:'Counting Atoms', q:'How many nitrogen atoms are in 75.0 g of ammonium sulfate, (NH4)2SO4 (M = 132.139 g/mol)?', answer:6.836e23, unit:'N atoms', tolerance:5e21, solution:'<p>mol compound = 75.0÷132.139 = 0.5676 mol. Each formula unit has 2 N atoms: mol N = 0.5676×2 = 1.1352 mol.<br>atoms N = 1.1352 × 6.022×10^23 = <strong>6.836 × 10^23 N atoms</strong></p>'},
  {id:'p134', difficulty:'hard', type:'multi', tag:'Mol–Particles', q:'If a 1.75 mol sample of Al2(SO4)3 fully dissociates (Al2(SO4)3 → 2Al^3+ + 3SO4^2-), how many total ions result?', answer:5.269e24, unit:'ions', tolerance:1e23, solution:'<p>1.75 mol Al2(SO4)3 → 3.50 mol Al^3+ + 5.25 mol SO4^2- = 8.75 mol total ions.<br>N = 8.75 × 6.022×10^23 = <strong>5.269 × 10^24 ions</strong></p>'},
  {id:'p135', difficulty:'hard', type:'concept', tag:'Molecular Formula', q:'A student computes the percent composition of a known compound, uses it to find the empirical formula, then finds the empirical formula matches the ORIGINAL molecular formula exactly (multiplier of 1). What does this tell you?', choices:['The compound\'s molecular formula already IS in the simplest whole-number ratio — no further reduction is possible', 'The student made an error, since molecular and empirical formulas should never be identical', 'The compound cannot exist', 'Percent composition calculations are only valid for elements, not compounds'], correct:0, solution:'<p>Some real compounds (like H2O, NH3, and CH4) have molecular formulas that are already in the simplest possible ratio. When this happens, the empirical and molecular formulas are identical — this is expected, not an error.</p>'},
  {id:'p136', difficulty:'hard', type:'multi', tag:'Gas at STP', q:'A flask contains 5.00 g of O2 gas and 5.00 g of N2 gas. What total volume does this mixture occupy at STP?', answer:7.503, unit:'L', tolerance:0.15, solution:'<p>mol O2 = 5.00÷31.998 = 0.1563 mol. mol N2 = 5.00÷28.014 = 0.1785 mol.<br>Total mol = 0.3348. V = 0.3348 × 22.414 = <strong>7.50 L</strong>. Note equal masses of different gases give very different mole counts because O2 and N2 have different molar masses.</p>'},
  {id:'p137', difficulty:'hard', type:'concept', tag:'Mole Concept', q:'Sample A is 10.0 g of H2 gas. Sample B is 10.0 g of O2 gas. Which sample contains MORE individual atoms, and why?', choices:['Sample A (H2) — it has both a lower molar mass (more moles per gram) AND more atoms per molecule-equivalent, compounding to a much larger atom count', 'Sample B (O2) — oxygen is a larger, heavier atom so it contributes more mass per atom', 'They contain the same number of atoms since both are diatomic', 'Cannot be determined without knowing the temperature'], correct:0, solution:'<p>H2 (M=2.016 g/mol) has far more moles per gram than O2 (M=31.998 g/mol) — roughly 16× more. Since both are diatomic (2 atoms per molecule), Sample A ends up with roughly 16× more atoms than Sample B despite having the same mass.</p>'},
  {id:'p138', difficulty:'hard', type:'multi', tag:'Molecular Formula', q:'A compound is 62.04% C, 10.41% H, and 27.55% O by mass, with a molar mass of approximately 116.2 g/mol. Find the molecular formula.', answer:'C6H12O2', unit:'', tolerance:0, isText:true, solution:'<p>mol C = 62.04÷12.011 = 5.166; mol H = 10.41÷1.008 = 10.327; mol O = 27.55÷15.999 = 1.722<br>Divide by 1.722 → C:3.00 H:6.00 O:1.00 → empirical C3H6O, M = 58.08 g/mol.<br>n = 116.2÷58.08 ≈ 2 → <strong>C6H12O2</strong></p>'},
  {id:'p139', difficulty:'hard', type:'multi', tag:'Molar Mass', q:'A 2.50 L sample of an unknown gas at STP has a mass of 4.91 g. Identify the gas.', answer:'CO2', unit:'', tolerance:0, isText:true, solution:'<p>mol = 2.50÷22.414 = 0.1115 mol. M = 4.91÷0.1115 = <strong>44.0 g/mol ≈ carbon dioxide (CO2, M=44.009)</strong></p>'},
  {id:'p140', difficulty:'hard', type:'multi', tag:'Percent Composition', q:'What is the mass of phosphorus in 40.0 g of calcium phosphate, Ca3(PO4)2 (M = 310.174 g/mol)?', answer:7.989, unit:'g P', tolerance:0.1, solution:'<p>%P = 2(30.974)÷310.174×100 = 61.948÷310.174×100 = 19.97%. mass P = 0.1997 × 40.0 = <strong>7.99 g</strong></p>'},
  {id:'p141', difficulty:'hard', type:'concept', tag:'Mole Concept', q:'Why must every gram-to-particles conversion pass THROUGH moles, rather than using a single direct conversion factor?', choices:['Because grams and particles are related by TWO separate physical constants (molar mass, which is substance-specific, and Avogadro\'s number, which is universal) — combining them requires the mole as the common intermediate unit', 'Because Avogadro\'s number only works with whole numbers of grams', 'Because particles cannot be measured directly in a lab', 'There is no real reason — it is just historical convention'], correct:0, solution:'<p>Molar mass (g/mol) links grams to moles, and Avogadro\'s number (particles/mol) links moles to particles. Since molar mass differs for every substance while Avogadro\'s number is universal, there is no single fixed constant connecting grams directly to particles — moles must serve as the bridge every time.</p>'},

  // ─── HARD EXPANSION BATCH — 30 additional hard problems ─────────────
  {id:'p142', difficulty:'hard', type:'multi', tag:'Empirical Formula', q:'A student burns a hydrocarbon sample and collects 1.320 g CO2 and 0.540 g H2O. What is the empirical formula?', answer:'C2H4', unit:'', tolerance:0, isText:true, solution:'<p>mol C = 1.320÷44.009 = 0.03000 mol. mol H = (0.540÷18.015)×2 = 0.05995 mol.<br>Divide by 0.03000 → C:1.00 H:2.00 → <strong>C2H4</strong> (ethylene — already in simplest ratio).</p>'},
  {id:'p143', difficulty:'hard', type:'multi', tag:'Hydrates', q:'A hydrate of sodium carbonate, Na2CO3·xH2O, has a total mass of 4.292 g. After heating, only 1.590 g of anhydrous Na2CO3 remains. Find x.', answer:'10', unit:'', tolerance:0, isText:true, solution:'<p>mass H2O lost = 4.292-1.590 = 2.702 g. mol Na2CO3 = 1.590÷105.988 = 0.01500 mol. mol H2O = 2.702÷18.015 = 0.1500 mol.<br>x = 0.1500÷0.01500 = <strong>10.0 ≈ 10</strong> (washing soda, Na2CO3·10H2O).</p>'},
  {id:'p144', difficulty:'hard', type:'multi', tag:'Gas at STP', q:'A container holds 6.40 g of O2 and 8.80 g of CO2. What total volume does this mixture occupy at STP?', answer:8.965, unit:'L', tolerance:0.15, solution:'<p>mol O2 = 6.40÷31.998 = 0.2000 mol. mol CO2 = 8.80÷44.009 = 0.2000 mol.<br>Total mol = 0.4000. V = 0.4000 × 22.414 = <strong>8.97 L</strong></p>'},
  {id:'p145', difficulty:'hard', type:'multi', tag:'Molar Mass', q:'A 12.0 g sample of an unknown gas contains 2.409 × 10^23 molecules. Identify the compound.', answer:'formaldehyde (CH2O)', unit:'', tolerance:0, isText:true, solution:'<p>mol = 2.409×10^23÷6.022×10^23 = 0.4000 mol. M = 12.0÷0.4000 = <strong>30.0 g/mol ≈ formaldehyde (CH2O, M=30.026)</strong></p>'},
  {id:'p146', difficulty:'hard', type:'multi', tag:'Percent Composition', q:'What is the percent composition of each element in sodium bicarbonate, NaHCO3 (M = 84.006 g/mol)?', answer:'%Na=27.37, %H=1.20, %C=14.30, %O=57.14', unit:'', tolerance:0, isText:true, solution:'<p>%Na = 22.990÷84.006×100 = <strong>27.37%</strong><br>%H = 1.008÷84.006×100 = <strong>1.20%</strong><br>%C = 12.011÷84.006×100 = <strong>14.30%</strong><br>%O = 3(15.999)÷84.006×100 = <strong>57.14%</strong></p>'},
  {id:'p147', difficulty:'hard', type:'multi', tag:'Counting Atoms', q:'How many nitrogen atoms are in 60.0 g of calcium nitrate, Ca(NO3)2 (M = 164.086 g/mol)?', answer:4.404e23, unit:'N atoms', tolerance:5e21, solution:'<p>mol compound = 60.0÷164.086 = 0.3657 mol. Each formula unit has 2 N atoms: mol N = 0.3657×2 = 0.7313 mol.<br>atoms N = 0.7313 × 6.022×10^23 = <strong>4.404 × 10^23 N atoms</strong></p>'},
  {id:'p148', difficulty:'hard', type:'multi', tag:'Mol–Particles', q:'If a 1.20 mol sample of Ca3(PO4)2 fully dissociates (Ca3(PO4)2 → 3Ca^2+ + 2PO4^3-), how many total ions result?', answer:3.613e24, unit:'ions', tolerance:1e23, solution:'<p>1.20 mol Ca3(PO4)2 → 3.60 mol Ca^2+ + 2.40 mol PO4^3- = 6.00 mol total ions.<br>N = 6.00 × 6.022×10^23 = <strong>3.613 × 10^24 ions</strong></p>'},
  {id:'p149', difficulty:'hard', type:'multi', tag:'Gas at STP', q:'A flask contains 4.00 g of He and 4.00 g of Ne. What total volume does this mixture occupy at STP?', answer:26.84, unit:'L', tolerance:0.3, solution:'<p>mol He = 4.00÷4.003 = 0.9993 mol. mol Ne = 4.00÷20.180 = 0.1982 mol.<br>Total mol = 1.1975. V = 1.1975 × 22.414 = <strong>26.84 L</strong>. Equal masses of very different molar masses give very different mole counts.</p>'},
  {id:'p150', difficulty:'hard', type:'multi', tag:'Percent Composition', q:'What is the mass of nitrogen in 55.0 g of ammonium sulfate, (NH4)2SO4 (M = 132.139 g/mol)?', answer:11.66, unit:'g N', tolerance:0.15, solution:'<p>%N = 2(14.007)÷132.139×100 = 28.014÷132.139×100 = 21.20%. mass N = 0.2120 × 55.0 = <strong>11.66 g</strong></p>'},
  {id:'p151', difficulty:'hard', type:'multi', tag:'Hydrates', q:'A hydrate of copper(II) sulfate, CuSO4·xH2O, has a total mass of 6.242 g. After heating, only 3.990 g of anhydrous CuSO4 remains. Find x.', answer:'5', unit:'', tolerance:0, isText:true, solution:'<p>mass H2O lost = 6.242-3.990 = 2.252 g. mol CuSO4 = 3.990÷159.607 = 0.02500 mol. mol H2O = 2.252÷18.015 = 0.1250 mol.<br>x = 0.1250÷0.02500 = <strong>5.00 ≈ 5</strong> (blue vitriol, CuSO4·5H2O).</p>'},
  {id:'p152', difficulty:'hard', type:'multi', tag:'Counting Atoms', q:'How many total atoms are in 0.0100 mol of CuSO4·5H2O (21 atoms per formula unit)?', answer:1.265e23, unit:'total atoms', tolerance:5e21, solution:'<p>mol atoms = 0.0100 × 21 = 0.2100 mol. N = 0.2100 × 6.022×10^23 = <strong>1.265 × 10^23 total atoms</strong></p>'},
  {id:'p153', difficulty:'hard', type:'multi', tag:'Mol–Particles', q:'How many molecules are in 18.5 g of ethanol (C2H5OH, M = 46.069 g/mol)?', answer:2.418e23, unit:'molecules', tolerance:5e21, solution:'<p>mol = 18.5÷46.069 = 0.4016 mol. N = 0.4016 × 6.022×10^23 = <strong>2.418 × 10^23 molecules</strong></p>'},
  {id:'p154', difficulty:'hard', type:'multi', tag:'Gas at STP', q:'What volume at STP does 9.00 g of sulfur dioxide (SO2, M = 64.063 g/mol) occupy?', answer:3.149, unit:'L', tolerance:0.05, solution:'<p>mol = 9.00÷64.063 = 0.1405 mol. V = 0.1405 × 22.414 = <strong>3.15 L</strong></p>'},
  {id:'p155', difficulty:'hard', type:'multi', tag:'Counting Atoms', q:'How many oxygen atoms are in 45.0 g of potassium nitrate (KNO3, M = 101.102 g/mol)?', answer:8.041e23, unit:'O atoms', tolerance:5e21, solution:'<p>mol KNO3 = 45.0÷101.102 = 0.4451 mol. Each formula unit has 3 O atoms: mol O = 0.4451×3 = 1.3352 mol.<br>atoms O = 1.3352 × 6.022×10^23 = <strong>8.04 × 10^23 O atoms</strong></p>'},
  {id:'p156', difficulty:'hard', type:'multi', tag:'Counting Atoms', q:'How many total atoms are in 5.00 g of ammonium phosphate, (NH4)3PO4 (M = 149.087 g/mol, 20 atoms per formula unit)?', answer:4.039e23, unit:'total atoms', tolerance:5e21, solution:'<p>mol compound = 5.00÷149.087 = 0.03354 mol. mol atoms = 0.03354×20 = 0.6707 mol.<br>N = 0.6707 × 6.022×10^23 = <strong>4.04 × 10^23 total atoms</strong></p>'},
  {id:'p157', difficulty:'hard', type:'multi', tag:'Percent Composition', q:'What is the percent composition of each element in magnesium nitride, Mg3N2 (M = 100.929 g/mol)?', answer:'%Mg=72.24, %N=27.76', unit:'', tolerance:0, isText:true, solution:'<p>%Mg = 3(24.305)÷100.929×100 = 72.915÷100.929×100 = <strong>72.24%</strong><br>%N = 2(14.007)÷100.929×100 = 28.014÷100.929×100 = <strong>27.76%</strong></p>'},
  {id:'p158', difficulty:'hard', type:'multi', tag:'Gram–Mol', q:'What is the mass of 4.50 × 10^24 formula units of potassium sulfate, K2SO4 (M = 174.257 g/mol)?', answer:1302, unit:'g', tolerance:15, solution:'<p>mol = 4.50×10^24÷6.022×10^23 = 7.472 mol. m = 7.472 × 174.257 = <strong>1302 g</strong> (about 1.30 kg).</p>'},
  {id:'p159', difficulty:'hard', type:'multi', tag:'Gas at STP', q:'A mixture contains 2.00 g of H2, 8.00 g of He, and 14.0 g of N2. What total volume does this mixture occupy at STP?', answer:78.23, unit:'L', tolerance:0.5, solution:'<p>mol H2 = 2.00÷2.016 = 0.9921 mol. mol He = 8.00÷4.003 = 1.9985 mol. mol N2 = 14.0÷28.014 = 0.4998 mol.<br>Total mol = 3.4904. V = 3.4904 × 22.414 = <strong>78.24 L</strong></p>'},
  {id:'p160', difficulty:'hard', type:'calc', tag:'Empirical Formula', q:'A compound is 63.65% N and 36.35% O by mass. What is the empirical formula?', answer:'N2O', unit:'', tolerance:0, isText:true, solution:'<p>mol N = 63.65÷14.007 = 4.544; mol O = 36.35÷15.999 = 2.272<br>Divide by 2.272 → N:2.00 O:1.00 → <strong>N2O</strong> (nitrous oxide, "laughing gas").</p>'},
  {id:'p161', difficulty:'hard', type:'multi', tag:'Molecular Formula', q:'A compound is 40.92% C, 4.58% H, and 54.50% O by mass, with a molar mass of approximately 176.1 g/mol. Find the molecular formula.', answer:'C6H8O6', unit:'', tolerance:0, isText:true, solution:'<p>mol C = 40.92÷12.011 = 3.407; mol H = 4.58÷1.008 = 4.544; mol O = 54.50÷15.999 = 3.407<br>Divide by 3.407 → C:1.00 H:1.33 O:1.00 → multiply by 3 → empirical C3H4O3, M = 88.06 g/mol.<br>n = 176.1÷88.06 ≈ 2 → <strong>C6H8O6</strong> (this is vitamin C, ascorbic acid).</p>'},
  {id:'p162', difficulty:'hard', type:'multi', tag:'Molecular Formula', q:'A compound is 92.26% C and 7.74% H by mass, with a molar mass of approximately 78.1 g/mol. Find the molecular formula.', answer:'C6H6', unit:'', tolerance:0, isText:true, solution:'<p>mol C = 92.26÷12.011 = 7.681; mol H = 7.74÷1.008 = 7.679<br>Divide by 7.679 → C:1.00 H:1.00 → empirical CH, M = 13.02 g/mol.<br>n = 78.1÷13.02 ≈ 6 → <strong>C6H6</strong> (benzene).</p>'},
  {id:'p163', difficulty:'hard', type:'multi', tag:'Mol–Particles', q:'If a 0.800 mol sample of Al2(SO4)3 fully dissociates (Al2(SO4)3 → 2Al^3+ + 3SO4^2-), how many total ions result?', answer:2.409e24, unit:'ions', tolerance:5e22, solution:'<p>0.800 mol Al2(SO4)3 → 1.60 mol Al^3+ + 2.40 mol SO4^2- = 4.00 mol total ions.<br>N = 4.00 × 6.022×10^23 = <strong>2.409 × 10^24 ions</strong></p>'},
  {id:'p164', difficulty:'hard', type:'concept', tag:'Molar Mass', q:'A student calculates an unknown compound\'s molar mass to be 45.0 g/mol using percent composition data, but the true molar mass (confirmed by mass spectrometry) is 90.0 g/mol. What is the most likely explanation?', choices:['The student correctly found the empirical formula mass, but the true molecular formula is exactly double the empirical formula — a multiplier of 2 was missed', 'The student made an arithmetic error and the true value is actually 45.0 g/mol', 'Percent composition can never be used to find molar mass', 'The compound has two different molar masses depending on conditions'], correct:0, solution:'<p>Percent composition alone can only ever give you the empirical formula mass — the simplest whole-number ratio. Without additional data (like the actual molar mass from another technique), you cannot know the multiplier. Here, the true molar mass is exactly double, meaning the molecular formula uses a multiplier of 2.</p>'},
  {id:'p165', difficulty:'hard', type:'concept', tag:'Molar Mass', q:'Compare 10.0 g of NaCl (M=58.443) to 10.0 g of Ca3(PO4)2 (M=310.174). Which sample contains more formula units, and roughly by what factor?', choices:['NaCl, by roughly a factor of 5 — since its molar mass is about 1/5th that of Ca3(PO4)2, the same mass gives about 5× more moles (and formula units)', 'Ca3(PO4)2, because it has more atoms per formula unit', 'They contain the same number of formula units since the masses are equal', 'Cannot be determined without knowing density'], correct:0, solution:'<p>Formula units per gram = Nₐ ÷ M. Since M(Ca3(PO4)2) ≈ 5.3 × M(NaCl), the same 10.0 g mass of NaCl yields roughly 5× more moles — and therefore roughly 5× more formula units — than Ca3(PO4)2.</p>'},
  {id:'p166', difficulty:'hard', type:'concept', tag:'Gas at STP', q:'Why do 1.00 mol of He gas and 1.00 mol of CO2 gas occupy the SAME volume (22.414 L) at STP, even though a CO2 molecule is much larger and heavier than a He atom?', choices:['At STP, gas volume is dominated by the empty space between widely-spaced, fast-moving particles — the tiny size of the individual particles themselves is essentially negligible compared to that empty space, so equal moles of any gas occupy essentially equal volume', 'He and CO2 happen to have the same molar mass', 'Gas volume depends only on temperature, not the substance', 'This is a coincidence specific to these two gases'], correct:0, solution:'<p>Ideal gas behavior means the actual volume of the gas particles themselves is negligible compared to the vast empty space between them. Since equal moles contain equal numbers of particles (by Avogadro\'s law), and the particle size barely matters, equal moles of ANY ideal gas occupy essentially the same volume at the same temperature and pressure.</p>'},
  {id:'p167', difficulty:'hard', type:'concept', tag:'Hydrates', q:'When determining the value of x in a hydrate formula like CuSO4·xH2O, why is it critical that ALL the water is driven off by heating, and none of the anhydrous salt itself decomposes?', choices:['If water remains, the mass loss will be too small, making x appear artificially low; if the salt decomposes, additional mass loss will make x appear artificially high — both errors corrupt the mol-ratio calculation that depends on an accurate water-to-salt mass split', 'It doesn\'t matter, since only the total starting mass is used in the calculation', 'The anhydrous salt always decomposes at the same temperature water evaporates, so this is not a real concern', 'x is a defined constant that doesn\'t depend on experimental mass measurements at all'], correct:0, solution:'<p>The x calculation depends entirely on correctly attributing the mass lost during heating to water ONLY. Any water left behind, or any decomposition of the salt itself, throws off the mass split between "water lost" and "anhydrous salt remaining," which directly corrupts the mol ratio (and therefore x).</p>'},
  {id:'p168', difficulty:'hard', type:'concept', tag:'Empirical Formula', q:'In combustion analysis of a compound containing C, H, and O, why is the oxygen content found by SUBTRACTION (total sample mass minus C mass minus H mass) rather than measured directly?', choices:['The combustion products (CO2 and H2O) only account for the carbon and hydrogen that came from the sample — any oxygen in the original sample gets mixed with the oxygen supplied by the combustion reaction itself, so it cannot be directly traced and isolated', 'Oxygen is impossible to detect in a laboratory', 'The sample never actually contains oxygen to begin with', 'Subtraction is simply a shortcut with no real justification'], correct:0, solution:'<p>Combustion analysis burns the sample in an oxygen-rich environment. The CO2 and H2O collected contain oxygen from BOTH the original sample AND the excess combustion oxygen, so that oxygen can\'t be cleanly separated by source. Instead, chemists find the C and H masses directly (from the known composition of CO2 and H2O), then assume any remaining mass in the original sample must have been oxygen.</p>'},
  {id:'p169', difficulty:'hard', type:'concept', tag:'Mole Concept', q:'A very small measurement uncertainty in molar mass (say, ±0.01 g/mol) becomes essentially irrelevant when converting a large lab-scale mass (like 500 g) into moles, but the SAME absolute uncertainty could matter more in a different scenario. Which scenario would that be?', choices:['Converting a very small mass (like 0.0050 g) into moles, where a ±0.01 g/mol shift in molar mass is a much larger fraction of the total, more strongly affecting the calculated mole value', 'Converting a very large mass, since larger numbers always amplify small errors', 'It never matters, since molar mass uncertainty is always negligible in every case', 'Uncertainty in molar mass only affects percent composition, never mole calculations'], correct:0, solution:'<p>Relative (percentage) impact of an absolute error scales inversely with the size of the calculation. A tiny fixed uncertainty in molar mass has a much larger relative effect when applied to very small sample masses, where the total moles being calculated are themselves very small.</p>'},
  {id:'p170', difficulty:'hard', type:'concept', tag:'Percent Composition', q:'A chemist analyzes a 2.00 g sample of a pure compound and finds it is 40.0% carbon by mass. If they instead analyzed a 200. g sample of the exact same compound, what percent carbon would they find?', choices:['Still 40.0% — percent composition is an intensive property that does not depend on sample size, only on the compound\'s fixed chemical formula', '4.00%, because the sample is 100× larger', '4000%, because the sample is 100× larger', 'It cannot be predicted without re-measuring'], correct:0, solution:'<p>Percent composition by mass is a ratio fixed by the compound\'s chemical formula (a fixed number of C atoms per formula unit relative to the whole formula mass) — it is independent of how much of the pure compound you happen to be measuring, just like density or melting point.</p>'},
  {id:'p171', difficulty:'hard', type:'concept', tag:'Mole Concept', q:'A teacher compares the mole to a "chemist\'s dozen." Which of the following best extends this analogy to explain why the mole is useful?', choices:['Just as "a dozen" lets you count eggs, donuts, or pencils using the same conversion (12 per dozen) regardless of what the items are, "a mole" lets you count atoms, molecules, or ions using the same conversion (6.022×10^23 per mole) regardless of the substance — bridging the invisibly small scale of particles to the measurable scale of grams', 'A dozen and a mole are both units of mass, so they measure the same kind of thing', 'The analogy fails completely because chemistry never involves counting', 'A mole only works for gases, unlike a dozen which works for anything'], correct:0, solution:'<p>The power of the mole (like the dozen) is that it is a pure counting unit — always exactly 6.022×10^23 particles, regardless of what those particles are. This lets chemists convert between the invisible particle count and the measurable mass (via molar mass) for ANY substance using the same universal bridge.</p>'},

  // ── 3 short easy multi-step problems (fill the multi+easy filter gap) ──
  {id:'p172', difficulty:'easy', type:'multi', tag:'Gram–Mol', q:'How many moles are in 10.0 g of NaOH (M = 39.997 g/mol)? Then, how many formula units is that?', answer:1.506e23, unit:'formula units', tolerance:2e21, solution:'<p>mol = 10.0÷39.997 = 0.2500 mol. formula units = 0.2500 × 6.022×10^23 = <strong>1.506 × 10^23</strong></p>'},
  {id:'p173', difficulty:'easy', type:'multi', tag:'Gas at STP', q:'How many moles are in 5.60 L of water vapor at STP? Then, what mass of water is that?', answer:4.501, unit:'g', tolerance:0.05, solution:'<p>mol = 5.60÷22.414 = 0.2498 mol. mass = 0.2498 × 18.015 = <strong>4.50 g</strong></p>'},
  {id:'p174', difficulty:'easy', type:'multi', tag:'Counting Atoms', q:'CO2 has 3 atoms per molecule. How many moles of atoms are in 0.500 mol of CO2?', answer:1.50, unit:'mol atoms', tolerance:0.01, solution:'<p>mol atoms = 0.500 mol × 3 atoms/molecule = <strong>1.50 mol atoms</strong></p>'}

]; // end ALL_PROBLEMS — 174 problems total (81 original + 60 added + 30 hard expansion + 3 easy multi-step)
